  INSERT INTO pl_meet_moves
INSERT INTO public.exercises (id, name, category, equipment, muscle_group, primary_muscle_group, muscle_groups, exercise_family,
INSERT INTO jn_stage.block VALUES
  ('3f736c8c-f785-4114-b3c5-d76f1af87a50'::uuid, '777c45d9-ad39-4a06-b8e0-04c6541d8a69', 'block-3', 2, 'Block 3 — Nationals Base', 'Calibration + Base Volume', 'Calibrate the Training Maxes (conventional deadlift set in Week 1) and build base volume on the competition lifts; Week 4 reduces fatigue.', 'Nationals base', 'Weeks 1–4 of the Nationals prep. Singles @6–7 with back-offs at 72.5–77.5% of the Training Max, overload bench and the priority accessories; Week 4 is easier on purpose.', 'Nationals prep Weeks 1–4 (Nov 15 – Dec 12). Squat TM 235 kg / bench TM 150 kg (Sep 20 2026 meet; Nov 9 squat 192.8 × 4 @6 ≈ 245 e1RM, Nov 12 bench 115.7 × 4 @6 ≈ 147). Conventional deadlift TM: not on file; Jared switched back from sumo Nov 7 and his only conventional set since is 224.5 kg × 4 @10 (Nov 13, ≈ 252 e1RM). Set it after Saturday Nov 21''s single @6 (about 95% of that single''s e1RM, floored to 2.5 kg). Review all three after Week 4.', 'Active', '2026-11-15'::date, '2026-12-12'::date, 4),
  ('657a0dbd-747f-44a7-af94-037bee9c896f'::uuid, 'bf538c45-3677-48a8-836b-f051fddd2972', 'block-4', 3, 'Block 4 — Nationals Strength', 'Strength', 'Triples at 77.5–82.5% with singles up to @8; the secondary squat becomes competition-stance paused; Week 8 reduces fatigue.', 'Nationals strength', 'Weeks 5–8. Back-offs move to triples, singles climb to @8 in Week 7 (never @9), Thursday''s squat becomes a competition-stance paused squat. Week 8 is easier, then the Training Maxes are reassessed for the peak.', 'Nationals prep Weeks 5–8 (Dec 13 – Jan 9). Training Maxes as set after the Week 4 review. After Week 8: reassess squat / bench / conventional deadlift TMs from several exposures and the RPE trend; these are the peak''s references.', 'Draft', '2026-12-13'::date, '2027-01-09'::date, 4),
  ('887f6705-82a0-45e7-92d6-0ab770c91318'::uuid, 'aa0df8da-77a3-4a78-b91e-8921b79a9f51', 'block-5', 4, 'Block 5 — Nationals Peak', 'Peak', 'Specificity: competition lifts only, heavy doubles and singles, then the final heavy exposures ~14 / 11 / 9 days out.', 'Nationals peak', 'Weeks 9–11. The block press, belt squat and deadlift variation are gone; heavy doubles at 82.5–85%, then the last heavy single for each lift in Week 11.', 'Nationals prep Weeks 9–11 (Jan 10 – Jan 30). Week 11''s sessions are counted back from Feb 8 and locked to their dates; when the lifting day is confirmed run pl_prep_set_meet_day to move them with it.', 'Draft', '2027-01-10'::date, '2027-01-30'::date, 3),
  ('f4a16ece-9988-4ed5-8cec-0a44943f05ae'::uuid, '599c30d4-c720-4db6-929d-77e5d8070ddd', 'block-6', 5, 'Block 6 — Nationals Taper', 'Taper', 'Fast, light competition lifts and a primer two days out.', 'Nationals taper', 'Week 12. Light, fast technique work and a primer two days before the lifting day (Feb 6 for a Feb 8 lift).', 'Nationals prep Week 12 (Jan 31 – Feb 6), anchored on Feb 8. Locked to meet-relative dates; moves with the confirmed lifting day (pl_prep_set_meet_day). Keep a bench exposure close to the meet: Jared responds well to it.', 'Draft', '2027-01-31'::date, '2027-02-06'::date, 1);
INSERT INTO jn_stage.week VALUES
  (1, '2026-11-15'::date, '2026-11-21'::date, '3f736c8c-f785-4114-b3c5-d76f1af87a50'::uuid, 1, 'Calibration + Base Volume', 'Week 1 of 12. Calibration + base volume. Singles @6, back-offs well under the cap. Squat and bench Training Maxes stay at 235 / 150 kg (Sep 20 meet) unless this week says otherwise; Saturday''s conventional single sets the deadlift Training Max.', 'Week 1 · Calibration', 'Singles @6 and light back-offs. Shows where your squat and bench Training Maxes sit, and Saturday''s conventional single sets your deadlift Training Max.'),
  (2, '2026-11-22'::date, '2026-11-28'::date, '3f736c8c-f785-4114-b3c5-d76f1af87a50'::uuid, 2, 'Base Volume', 'Week 2 of 12. Base volume: singles @6.5, back-offs 72.5–75% with the cap at @6–7.', 'Week 2 · Base volume', 'Singles @6.5, back-offs at 75% of the Training Max. Same exercises, a little more load.'),
  (3, '2026-11-29'::date, '2026-12-05'::date, '3f736c8c-f785-4114-b3c5-d76f1af87a50'::uuid, 3, 'Base Volume', 'Week 3 of 12. Heaviest base week: singles @7, back-offs 75–77.5% with the cap at @7.', 'Week 3 · Heaviest base week', 'Singles @7, back-offs at 77.5%. The last push of the base phase before an easier week.'),
  (4, '2026-12-06'::date, '2026-12-12'::date, '3f736c8c-f785-4114-b3c5-d76f1af87a50'::uuid, 4, 'Fatigue Reduction', 'Week 4 of 12. Fatigue reduction, easier on purpose. After this week the coach reviews squat / bench / conventional deadlift e1RM, RPE accuracy, bar speed, recovery, adherence and bodyweight, and updates a Training Max only if the trend says so (never from one strong session).', 'Week 4 · Fatigue reduction', 'Deliberately easier: singles @6, fewer back-offs, accessories trimmed. Training Max review after this week.'),
  (5, '2026-12-13'::date, '2026-12-19'::date, '657a0dbd-747f-44a7-af94-037bee9c896f'::uuid, 1, 'Strength', 'Week 5 of 12. Strength phase begins: back-offs move to triples at 77.5%, and Thursday''s secondary squat becomes the competition-stance paused squat.', 'Week 5 · Strength begins', 'Triples now. Thursday''s squat becomes a competition-stance paused squat: more specific from here.'),
  (6, '2026-12-20'::date, '2026-12-26'::date, '657a0dbd-747f-44a7-af94-037bee9c896f'::uuid, 2, 'Strength', 'Week 6 of 12. Strength: singles @7.5, back-offs 3×3 at 80% with the cap at @7–7.5.', 'Week 6 · Strength', 'Singles @7.5, triples at 80% of the Training Max.'),
  (7, '2026-12-27'::date, '2027-01-02'::date, '657a0dbd-747f-44a7-af94-037bee9c896f'::uuid, 3, 'Strength (hardest week)', 'Week 7 of 12. The hardest accumulation week: singles @8 (never turn one into @9), back-offs at 80–82.5% capped at @8. Optional work stays optional.', 'Week 7 · Hardest week', 'Singles @8, never @9. The hardest accumulation week before the second fatigue reduction.'),
  (8, '2027-01-03'::date, '2027-01-09'::date, '657a0dbd-747f-44a7-af94-037bee9c896f'::uuid, 4, 'Fatigue Reduction', 'Week 8 of 12. Fatigue reduction. After this week the competition Training Maxes are reassessed from several exposures and the RPE trend: these become the references for the peak. Don''t chase an optimistic e1RM.', 'Week 8 · Fatigue reduction', 'Second easier week. After it, the squat, bench and deadlift Training Maxes are reassessed for the peak.'),
  (9, '2027-01-10'::date, '2027-01-16'::date, '887f6705-82a0-45e7-92d6-0ab770c91318'::uuid, 1, 'Peak', 'Week 9 of 12. Peak begins: non-specific work disappears. Close-grip block press becomes competition bench technique, Thursday''s squat becomes competition squat technique, no belt squat and no deadlift variation.', 'Week 9 · Peak begins', 'Specificity takes over: the block press and belt squat are gone, everything moves toward the platform.'),
  (10, '2027-01-17'::date, '2027-01-23'::date, '887f6705-82a0-45e7-92d6-0ab770c91318'::uuid, 2, 'Peak', 'Week 10 of 12. Peak: singles @8–8.5 and doubles at 85%. If the first double is over @7.5, stop there.', 'Week 10 · Peak', 'Heavy doubles at 85% behind singles @8–8.5. Stop at one back-off if the first is already hard.'),
  (11, '2027-01-24'::date, '2027-01-30'::date, '887f6705-82a0-45e7-92d6-0ab770c91318'::uuid, 3, 'Final Heavy Exposures', 'Week 11 of 12. Final meaningful heavy exposures, counted from Feb 8 (the conservative meet anchor): squat Monday (~14 days out), bench Thursday (~11), deadlift Saturday (~9). Don''t max out. These dates move with the actual lifting day once it''s confirmed.', 'Week 11 · Final heavy work', 'The last meaningful heavy single for each lift: squat ~14 days out, bench ~11, deadlift ~9 (from Feb 8). Strong and clean, never a grinder.'),
  (12, '2027-01-31'::date, '2027-02-06'::date, 'f4a16ece-9988-4ed5-8cec-0a44943f05ae'::uuid, 1, 'Taper', 'Week 12 of 12. Taper, anchored on Feb 8 (the earliest day of the Feb 8–13 window). Once the exact lifting day is confirmed these sessions move with it, keeping their distance from the meet; Weeks 1–10 stay as they are.', 'Week 12 · Taper', 'Everything fast and light, nothing above @4–5. Saturday''s primer is for a Feb 8 lifting day and moves with the confirmed day.');
