INSERT INTO jn_stage.note VALUES
  (1, 'Top single @6. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Calibration: confirms where your squat Training Max sits. Rest 5–7 min.'),
  (2, 'Back-offs: 72.5% of your Competition Squat Training Max. RPE cap @6: the cap beats the %, so if a set goes over @6, take weight off the next. Rest 5–7 min.'),
  (3, 'Bench/triceps overload: grip a little narrower than competition, press off 2–4 in blocks, full lockout. Rest 3–4 min.'),
  (4, 'Back-off set. Bench/triceps overload: grip a little narrower than competition, press off 2–4 in blocks, full lockout. Rest 3–4 min.'),
  (5, '1 hard set after warm-ups. Double progression: beat last time''s reps; at the top of the range at the target RPE, add the smallest jump. Never add sets.'),
  (6, '1 hard set after warm-ups. Double progression: beat last time''s reps; at the top of the range at the target RPE, add the smallest jump. Never add sets. Never to soreness that touches your squat or deadlift.'),
  (7, 'Optional. Low-fatigue conventional technique pull: competition setup, pause 1–2 s just off the floor holding position, finish, reset every rep. If the one set feels unusually fatiguing, stop: never a second deadlift workout. Skip it if Saturday''s deadlift went backwards, your low back or hamstrings are still tired, or sleep has slipped. Go by the RPE: Saturday sets the deadlift Training Max.'),
  (8, '1 hard set after warm-ups. Double progression: beat last time''s reps; at the top of the range at the target RPE, add the smallest jump. Never add sets. Lat bias: elbows tight to the sides, pull toward the hip.'),
  (9, '2 hard sets (priority muscle). Double progression: reps first, then the smallest jump. Never a third set.'),
  (10, '1 hard set after warm-ups. Double progression: beat last time''s reps; at the top of the range at the target RPE, add the smallest jump. Never add sets. 1–2 working sets: add the 2nd only if time allows. A cable crunch works too.'),
  (11, 'Optional. 1 hard set after warm-ups. Double progression: beat last time''s reps; at the top of the range at the target RPE, add the smallest jump. Never add sets.'),
  (12, 'Zone 2: incline walk or bike, conversational pace. 10–15 min. 10 minutes done beats 30 skipped.'),
  (13, 'Secondary squat: upright torso, controlled depth, crisp reps, never a grind. Load: 67.5% of your Competition Squat Training Max. RPE cap @5: the cap beats the %. Rest 4–5 min.'),
  (14, 'Top single @6. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Calibration: confirms where your bench Training Max sits. Sharp low-back pain getting out of your setup (like Oct 23)? Stop, use a back-friendly setup and flag it for your coach. Rest 4–5 min.'),
  (15, 'Back-offs: 72.5% of your Competition Bench Training Max. RPE cap @6: the cap beats the %, so if a set goes over @6, take weight off the next. Rest 4–5 min.'),
  (16, 'Optional. Zone 2: incline walk or bike, conversational pace. Only if time and energy are good. 10 minutes done beats 30 skipped.'),
  (17, 'Top single @6, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Calibration: this sets your conventional Competition Deadlift Training Max. Rest 6–8 min.'),
  (18, 'Back-offs: 77.5% of today''s single (≈ 70–72.5% of a Training Max; there''s no conventional Training Max yet, so they read from the single you just logged). RPE cap @6: the cap beats the %, so if the first is over @6, take weight off. Rest 6–8 min.'),
  (19, 'Secondary bench: full 2-count pause on the chest, competition grip. Load: 70% of your Competition Bench Training Max. RPE cap @5: the cap beats the %. Rest 3–4 min.'),
  (20, 'Top single @6.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 5–7 min.'),
  (21, 'Back-offs: 75% of your Competition Squat Training Max. RPE cap @7: the cap beats the %, so if a set goes over @7, take weight off the next. Rest 5–7 min.'),
  (22, 'Optional. Low-fatigue conventional technique pull: competition setup, pause 1–2 s just off the floor holding position, finish, reset every rep. If the one set feels unusually fatiguing, stop: never a second deadlift workout. Skip it if Saturday''s deadlift went backwards, your low back or hamstrings are still tired, or sleep has slipped. Load: about 60% of your Competition Deadlift Training Max; no Training Max on file yet, go by the RPE. RPE cap @5.'),
  (23, 'Secondary squat: upright torso, controlled depth, crisp reps, never a grind. Load: 70% of your Competition Squat Training Max. RPE cap @6: the cap beats the %. Rest 4–5 min.'),
  (24, 'Top single @6.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Sharp low-back pain getting out of your setup (like Oct 23)? Stop, use a back-friendly setup and flag it for your coach. Rest 4–5 min.'),
  (25, 'Back-offs: 75% of your Competition Bench Training Max. RPE cap @7: the cap beats the %, so if a set goes over @7, take weight off the next. Rest 4–5 min.'),
  (26, 'Top single @6.5, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 6–8 min.'),
  (27, 'Back-offs: 72.5–75% of your Competition Deadlift Training Max (set from Week 1''s conventional single; if none is on file yet, go by the RPE cap). The app loads 72.5%; go to 75% only if the single moved well and you''re under the cap. RPE cap @7: the cap beats the %, so if a set goes over @7, take weight off the next. Rest 6–8 min.'),
  (28, 'Secondary bench: full 2-count pause on the chest, competition grip. Load: 72.5% of your Competition Bench Training Max. RPE cap @6: the cap beats the %. Rest 3–4 min.'),
  (29, 'Top single @7. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 5–7 min.'),
  (30, 'Back-offs: 77.5% of your Competition Squat Training Max. RPE cap @7: the cap beats the %, so if a set goes over @7, take weight off the next. If the third back-off would go over @7, stop at two. Rest 5–7 min.'),
  (31, 'Optional. Low-fatigue conventional technique pull: competition setup, pause 1–2 s just off the floor holding position, finish, reset every rep. If the one set feels unusually fatiguing, stop: never a second deadlift workout. Skip it if Saturday''s deadlift went backwards, your low back or hamstrings are still tired, or sleep has slipped. No extra set unless the first is extremely easy and there''s a clear reason. Load: about 60% of your Competition Deadlift Training Max; no Training Max on file yet, go by the RPE. RPE cap @6.'),
  (32, 'Secondary squat: upright torso, controlled depth, crisp reps, never a grind. Load: 72.5% of your Competition Squat Training Max. RPE cap @6: the cap beats the %. Rest 4–5 min.'),
  (33, 'Top single @7. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Sharp low-back pain getting out of your setup (like Oct 23)? Stop, use a back-friendly setup and flag it for your coach. Rest 4–5 min.'),
  (34, 'Back-offs: 77.5% of your Competition Bench Training Max. RPE cap @7: the cap beats the %, so if a set goes over @7, take weight off the next. If the third back-off would go over @7, stop at two. Rest 4–5 min.'),
  (35, 'Top single @7, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 6–8 min.'),
  (36, 'Back-offs: 75–77.5% of your Competition Deadlift Training Max (set from Week 1''s conventional single; if none is on file yet, go by the RPE cap). The app loads 75%; go to 77.5% only if the single moved well and you''re under the cap. RPE cap @7: the cap beats the %, so if a set goes over @7, take weight off the next. Rest 6–8 min.'),
  (37, 'Secondary bench: full 2-count pause on the chest, competition grip. Load: 75% of your Competition Bench Training Max. RPE cap @6: the cap beats the %. Rest 3–4 min.'),
  (38, 'Top single @6. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 5–7 min.'),
  (39, 'Back-offs: 67.5–70% of your Competition Squat Training Max. The app loads 67.5%; go to 70% only if the single moved well and you''re under the cap. RPE cap @6: the cap beats the %, so if a set goes over @6, take weight off the next. Rest 5–7 min.'),
  (40, 'Fatigue reduction: easier on purpose. Same load or a touch lighter, 2–3 reps in the tank.'),
  (41, 'Fatigue reduction: easier on purpose. Same load or a touch lighter, 2–3 reps in the tank. Never to soreness that touches your squat or deadlift.'),
  (42, 'Fatigue reduction: easier on purpose. Same load or a touch lighter, 2–3 reps in the tank. 1 set.'),
  (43, 'Optional. Zone 2: incline walk or bike, conversational pace. 10 minutes done beats 30 skipped.'),
  (44, 'Secondary squat: upright torso, controlled depth, easy and crisp. Load: 65% of your Competition Squat Training Max. RPE cap @5: the cap beats the %. Rest 4–5 min.'),
  (45, 'Top single @6. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 4–5 min.'),
  (46, 'Back-offs: 70% of your Competition Bench Training Max. RPE cap @6: the cap beats the %, so if a set goes over @6, take weight off the next. Rest 4–5 min.'),
  (47, 'Top single @6, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 6–8 min.'),
  (48, 'Back-offs: 67.5–70% of your Competition Deadlift Training Max (set from Week 1''s conventional single; if none is on file yet, go by the RPE cap). The app loads 67.5%; go to 70% only if the single moved well and you''re under the cap. RPE cap @6: the cap beats the %, so if a set goes over @6, take weight off the next. 1–2 sets: add a 2nd only if the first was fast and no harder than @6. Rest 6–8 min.'),
  (49, 'Secondary bench: full 2-count pause, easy. Load: 67.5% of your Competition Bench Training Max. RPE cap @5: the cap beats the %. Rest 3–4 min.'),
  (50, 'Back-offs: 77.5% of your Competition Squat Training Max. RPE cap @7: the cap beats the %, so if a set goes over @7, take weight off the next. Rest 5–7 min.'),
  (51, 'Competition-stance paused squat: your competition stance and bar position, a clean 1–2 s pause in the hole, stay tight, drive up. Load: 62.5–65% of your Competition Squat Training Max (the app loads 62.5%). RPE cap @6: the cap beats the %. Rest 4–5 min.'),
  (52, 'Back-offs: 77.5% of your Competition Bench Training Max. RPE cap @7: the cap beats the %, so if a set goes over @7, take weight off the next. Rest 4–5 min.'),
  (53, 'Top single @7.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 5–7 min.'),
  (54, 'Back-offs: 80% of your Competition Squat Training Max. RPE cap @7.5: the cap beats the %, so if a set goes over @7.5, take weight off the next. Rest 5–7 min.'),
  (55, 'Optional. Low-fatigue conventional technique pull: competition setup, pause 1–2 s just off the floor holding position, finish, reset every rep. If the one set feels unusually fatiguing, stop: never a second deadlift workout. Skip it if Saturday''s deadlift went backwards, your low back or hamstrings are still tired, or sleep has slipped. If Saturday''s deadlift recovery has got worse, take it out this week. Load: about 62.5% of your Competition Deadlift Training Max; no Training Max on file yet, go by the RPE. RPE cap @6.'),
  (56, 'Competition-stance paused squat: your competition stance and bar position, a clean 1–2 s pause in the hole, stay tight, drive up. Load: 65–67.5% of your Competition Squat Training Max (the app loads 65%). RPE cap @6: the cap beats the %. Rest 4–5 min.'),
  (57, 'Top single @7.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Sharp low-back pain getting out of your setup (like Oct 23)? Stop, use a back-friendly setup and flag it for your coach. Rest 4–5 min.'),
  (58, 'Back-offs: 80% of your Competition Bench Training Max. RPE cap @7.5: the cap beats the %, so if a set goes over @7.5, take weight off the next. Rest 4–5 min.'),
  (59, 'Top single @7.5, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 6–8 min.'),
  (60, 'Back-offs: 77.5–80% of your Competition Deadlift Training Max (set from Week 1''s conventional single; if none is on file yet, go by the RPE cap). The app loads 77.5%; go to 80% only if the single moved well and you''re under the cap. RPE cap @7.5: the cap beats the %, so if a set goes over @7.5, take weight off the next. Rest 6–8 min.'),
  (61, 'Secondary bench: full 2-count pause on the chest, competition grip. Load: 77.5% of your Competition Bench Training Max. RPE cap @7: the cap beats the %. Rest 3–4 min.'),
  (62, 'Top single @8. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Do not turn the single into @9. Rest 5–7 min.'),
  (63, 'Back-offs: 82.5% of your Competition Squat Training Max. RPE cap @8: the cap beats the %, so if a set goes over @8, take weight off the next. Rest 5–7 min.'),
  (64, 'Back-off set. Bench/triceps overload: grip a little narrower than competition, press off 2–4 in blocks, full lockout. Optional 2nd set: only if recovery is excellent. Rest 3–4 min.'),
  (65, 'Optional. Low-fatigue conventional technique pull: competition setup, pause 1–2 s just off the floor holding position, finish, reset every rep. If the one set feels unusually fatiguing, stop: never a second deadlift workout. Skip it if Saturday''s deadlift went backwards, your low back or hamstrings are still tired, or sleep has slipped. Do not go past this. Load: about 60% of your Competition Deadlift Training Max; no Training Max on file yet, go by the RPE. RPE cap @5.'),
  (66, 'Competition-stance paused squat: your competition stance and bar position, a clean 1–2 s pause in the hole, stay tight, drive up. Load: 67.5–70% of your Competition Squat Training Max (the app loads 67.5%). RPE cap @7: the cap beats the %. Rest 4–5 min.'),
  (67, 'Top single @8. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Do not turn the single into @9. Sharp low-back pain getting out of your setup (like Oct 23)? Stop, use a back-friendly setup and flag it for your coach. Rest 4–5 min.'),
  (68, 'Back-offs: 82.5% of your Competition Bench Training Max. RPE cap @8: the cap beats the %, so if a set goes over @8, take weight off the next. Rest 4–5 min.'),
  (69, 'Top single @8, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Do not exceed @8. Rest 6–8 min.'),
  (70, 'Back-offs: 80% of your Competition Deadlift Training Max (set from Week 1''s conventional single; if none is on file yet, go by the RPE cap). RPE cap @8: the cap beats the %, so if a set goes over @8, take weight off the next. 1–2 sets: do the 2nd only if the first was no harder than @7.5 and moved well. Rest 6–8 min.'),
  (71, 'Secondary bench: full 2-count pause on the chest, competition grip. Load: 80% of your Competition Bench Training Max. RPE cap @7: the cap beats the %. Rest 3–4 min.'),
  (72, 'Top single @6–6.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 5–7 min.'),
  (73, 'Back-offs: 70–72.5% of your Competition Squat Training Max. The app loads 70%; go to 72.5% only if the single moved well and you''re under the cap. RPE cap @6.5: the cap beats the %, so if a set goes over @6.5, take weight off the next. Rest 5–7 min.'),
  (74, 'Competition-stance paused squat, easy and crisp. Load: 62.5% of your Competition Squat Training Max. RPE cap @5: the cap beats the %. Rest 4–5 min.'),
  (75, 'Top single @6–6.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 4–5 min.'),
  (76, 'Back-offs: 72.5% of your Competition Bench Training Max. RPE cap @6.5: the cap beats the %, so if a set goes over @6.5, take weight off the next. Rest 4–5 min.'),
  (77, 'Top single @6–6.5, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 6–8 min.'),
  (78, 'Back-offs: 70–72.5% of your Competition Deadlift Training Max (set from Week 1''s conventional single; if none is on file yet, go by the RPE cap). The app loads 70%; go to 72.5% only if the single moved well and you''re under the cap. RPE cap @6.5: the cap beats the %, so if a set goes over @6.5, take weight off the next. 1–2 sets: add a 2nd only if the first was fast and no harder than @6.5. Rest 6–8 min.'),
  (79, 'Top single @8. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 5–7 min.'),
  (80, 'Competition bench technique: competition grip, pause and commands, every rep identical. Load: 70% of your Competition Bench Training Max. RPE cap @6: the cap beats the %. Rest 3–4 min.'),
  (81, 'Peak: crisp, short of a grind. Nothing that leaves you sore for squat or deadlift.'),
  (82, 'Peak: crisp, short of a grind. Nothing that leaves you sore for squat or deadlift. 1 set.'),
  (83, 'Zone 2: incline walk or bike, conversational pace. 10 minutes at most. 10 minutes done beats 30 skipped.'),
  (84, 'Competition squat technique: competition stance, depth and commands, every rep identical. Load: 70% of your Competition Squat Training Max. RPE cap @6: the cap beats the %. Rest 4–5 min.'),
  (85, 'Top single @8. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Sharp low-back pain getting out of your setup (like Oct 23)? Stop, use a back-friendly setup and flag it for your coach. Rest 4–5 min.'),
  (86, 'Top single @8, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 6–8 min.'),
  (87, 'Back-offs: 80–82.5% of your Competition Deadlift Training Max (set from Week 1''s conventional single; if none is on file yet, go by the RPE cap). The app loads 80%; go to 82.5% only if the single moved well and you''re under the cap. RPE cap @8: the cap beats the %, so if a set goes over @8, take weight off the next. Rest 6–8 min.'),
  (88, 'Competition-style 2-count paused bench: competition grip and commands. Load: 70–72.5% of your Competition Bench Training Max (the app loads 70%). RPE cap @6: the cap beats the %. Rest 3–4 min.'),
  (89, 'Top single @8–8.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 5–7 min.'),
  (90, 'Back-offs: 85% of your Competition Squat Training Max. RPE cap @7.5: the cap beats the %, so if a set goes over @7.5, take weight off the next. 1–2 sets: if the first double is already over @7.5, stop at one. Rest 5–7 min.'),
  (91, 'Competition bench technique: competition grip, pause and commands. Load: 72.5% of your Competition Bench Training Max. RPE cap @6: the cap beats the %. Rest 3–4 min.'),
  (92, 'Optional. Zone 2: incline walk or bike, conversational pace. Easy. 10 minutes done beats 30 skipped.'),
  (93, 'Competition squat technique: competition stance, depth and commands. Load: 72.5% of your Competition Squat Training Max. RPE cap @6: the cap beats the %. Rest 4–5 min.'),
  (94, 'Top single @8–8.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Sharp low-back pain getting out of your setup (like Oct 23)? Stop, use a back-friendly setup and flag it for your coach. Rest 4–5 min.'),
  (95, 'Back-offs: 85% of your Competition Bench Training Max. RPE cap @7.5: the cap beats the %, so if a set goes over @7.5, take weight off the next. 1–2 sets: if the first double is already over @7.5, stop at one. Rest 4–5 min.'),
  (96, 'Top single @8–8.5, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Rest 6–8 min.'),
  (97, 'Back-offs: 82.5% of your Competition Deadlift Training Max (set from Week 1''s conventional single; if none is on file yet, go by the RPE cap). RPE cap @8: the cap beats the %, so if a set goes over @8, take weight off the next. No extra back-off unless your coach says it''s clearly warranted. Rest 6–8 min.'),
  (98, 'Competition-style 2-count paused bench: competition grip and commands. Load: 72.5–75% of your Competition Bench Training Max (the app loads 72.5%). RPE cap @6: the cap beats the %. Rest 3–4 min.'),
  (99, 'Top single @8–8.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Final heavy squat: strong, clean, confidence-building. Not a grinder. Rest 5–7 min.'),
  (100, 'Optional. Back-offs: 75–80% of your Competition Squat Training Max. The app loads 75%; go to 80% only if the single moved well and you''re under the cap. RPE cap @6: the cap beats the %, so if a set goes over @6, take weight off the next. Only if it improves readiness; skip it if the single was a fight. Rest 5–7 min.'),
  (101, 'Competition bench singles: competition commands, fast. Load: 70% of your Competition Bench Training Max. RPE cap @6: the cap beats the %. Rest 3–4 min.'),
  (102, 'Taper: easy, 3+ reps in the tank.'),
  (103, 'Taper: easy, 3+ reps in the tank. 1 set.'),
  (104, 'Optional. Zone 2: incline walk or bike, conversational pace. A 10-minute walk or bike. 10 minutes done beats 30 skipped.'),
  (105, 'Light competition squat: competition stance and commands, fast. Load: 60–65% of your Competition Squat Training Max (the app loads 60%). RPE cap @5: the cap beats the %. Rest 4–5 min.'),
  (106, 'Top single @8–8.5. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. Final heavy bench: strong and clean, not a grinder. Rest 4–5 min.'),
  (107, 'Optional. Back-offs: 75–80% of your Competition Bench Training Max. The app loads 75%; go to 80% only if the single moved well and you''re under the cap. RPE cap @6: the cap beats the %, so if a set goes over @6, take weight off the next. Only if it improves readiness. Rest 4–5 min.'),
  (108, 'Top single @7.5–8, conventional. Attempt-style jumps, competition commands. The day''s read, not a test: log the weight and an honest RPE. The final meaningful deadlift. Do not chase @9; no back-off. Rest 6–8 min.'),
  (109, 'Competition bench: competition commands, fast and identical. Load: 65–70% of your Competition Bench Training Max (the app loads 65%). RPE cap @5: the cap beats the %. Rest 3–4 min.'),
  (110, 'Optional. Taper: easy, 3+ reps in the tank.'),
  (111, 'Fast competition squats with commands. Load: 60–65% of your Competition Squat Training Max (the app loads 60%). RPE cap @5: the cap beats the %. Rest 5–7 min.'),
  (112, 'Fast competition bench with commands. Load: 60–65% of your Competition Bench Training Max (the app loads 60%). RPE cap @5: the cap beats the %. Rest 4–5 min.'),
  (113, 'One fast conventional single. Load: 55–60% of your Competition Deadlift Training Max (the app loads 55%). No Training Max on file? Go by the RPE. RPE cap @5: the cap beats the %. Rest 6–8 min.'),
  (114, 'Optional. Zone 2: incline walk or bike, conversational pace. 10–15 min of easy movement if you want it. 10 minutes done beats 30 skipped.'),
  (115, '1–2 fast singles with commands; one is enough if it felt perfect. Load: 50–55% of your Competition Squat Training Max (the app loads 50%). RPE cap @4: the cap beats the %. Rest 5–7 min.'),
  (116, 'Fast competition bench singles with commands. Load: 55–60% of your Competition Bench Training Max (the app loads 55%). RPE cap @4: the cap beats the %. Rest 4–5 min.'),
  (117, 'One crisp single with commands. Load: 40–50% of your Competition Squat Training Max (the app loads 40%). RPE cap @4: the cap beats the %. Rest 5–7 min.'),
  (118, '1–2 crisp singles with commands. Load: 40–50% of your Competition Bench Training Max (the app loads 40%). RPE cap @4: the cap beats the %. Rest 4–5 min.'),
  (119, 'Optional. A single if you want it: leave it out if you feel better without a pull this close. Load: 40% of your Competition Deadlift Training Max. No Training Max on file? Go by the RPE. RPE cap @4: the cap beats the %. Rest 6–8 min.'),
  (120, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory before any squat or bench work. Calibration week: the single and the back-offs help confirm your squat Training Max.'),
  (121, 'Target 45–60 min. Low-fatigue development: nothing here should make Saturday''s deadlift harder. Over 60 min? Drop the optional work first. Order to drop if you''re short on time: curl, the 2nd ab set, then the paused pull.'),
  (122, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory, never the bench work. Calibration week: the bench single and back-offs help confirm your bench Training Max.'),
  (123, 'Target 75–90 min. The one deadlift day that matters each week: everything else is built around it. Over 90 min? Cut the last accessory. Calibration: this single @6 and the back-offs set your conventional Competition Deadlift Training Max. Log the single''s weight and RPE carefully.'),
  (124, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory before any squat or bench work.'),
  (125, 'Target 45–60 min. Low-fatigue development: nothing here should make Saturday''s deadlift harder. Over 60 min? Drop the optional work first.'),
  (126, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory, never the bench work.'),
  (127, 'Target 75–90 min. The one deadlift day that matters each week: everything else is built around it. Over 90 min? Cut the last accessory.'),
  (128, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory before any squat or bench work. Fatigue reduction: no belt squat unless you feel exceptionally recovered.'),
  (129, 'Target 45–60 min. Low-fatigue development: nothing here should make Saturday''s deadlift harder. Over 60 min? Drop the optional work first. No deadlift variation this week.'),
  (130, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory, never the bench work. Fatigue reduction.'),
  (131, 'Target 75–90 min. The one deadlift day that matters each week: everything else is built around it. Over 90 min? Cut the last accessory. Fatigue reduction. After today: Training Max review (squat, bench, conventional deadlift).'),
  (132, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory before any squat or bench work. Belt squat is optional this week.'),
  (133, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory before any squat or bench work. Fatigue reduction.'),
  (134, 'Target 75–90 min. The one deadlift day that matters each week: everything else is built around it. Over 90 min? Cut the last accessory. Fatigue reduction. After today: Training Max reassessment for the peak.'),
  (135, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory before any squat or bench work. Peak: no belt squat.'),
  (136, 'Target 45–60 min. Low-fatigue development: nothing here should make Saturday''s deadlift harder. Over 60 min? Drop the optional work first. No deadlift variation unless your coach asks for one for a technical reason (then 1×3 @5 at most).'),
  (137, 'Target 45–60 min. Low-fatigue development: nothing here should make Saturday''s deadlift harder. Over 60 min? Drop the optional work first. No deadlift variation.'),
  (138, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory before any squat or bench work. Final heavy squat: strong, technically clean, confidence-building. Not a grinder.'),
  (139, 'Target 30–45 min. No deadlift. No fatigue chasing: leave fresher than you came in.'),
  (140, 'Target 75–90 min. % loads are planned weights; the RPE cap always wins. Over 90 min? Cut the last accessory, never the bench work. Final heavy bench: strong and clean, not a grinder.'),
  (141, 'Target 45–60 min. The final meaningful deadlift: @7.5–8, never chase @9. No back-off. No meaningful lower-body accessory fatigue.'),
  (142, 'Target 45–60 min. Everything should move fast: nothing above about @4–5. Then leave.'),
  (143, 'No lifting required. If you want it: 10–15 min of easy movement, light abs or mobility. No fatigue.'),
  (144, 'Target 30–45 min. A technique touch, no meaningful deadlift work.'),
  (145, 'Target 20–30 min. Two days before your lifting day: Feb 6 is for a Feb 8 lift, and it moves to two days before your actual day once that''s confirmed. It should feel almost too easy.');
